import sys

def solve():
    data = sys.stdin.read().split()
    H = int(data[0])
    W = int(data[1])
    grid = data[2:2 + H]

    min_r, max_r = H, -1
    min_c, max_c = W, -1

    for i in range(H):
        for j, ch in enumerate(grid[i]):
            if ch == '#':
                min_r = min(min_r, i)
                max_r = max(max_r, i)
                min_c = min(min_c, j)
                max_c = max(max_c, j)

    for i in range(min_r, max_r + 1):
        for j in range(min_c, max_c + 1):
            if grid[i][j] == '.':
                print("No")
                return

    print("Yes")

if __name__ == "__main__":
    solve()
